<?php require "../config.php";$page_title="Admissions";$programs=$conn->query("SELECT * FROM programs ORDER BY name");$ok=false;if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO applications(name,email,phone,program_id) VALUES(?,?,?,?)");$s->bind_param("sssi",$_POST["name"],$_POST["email"],$_POST["phone"],$_POST["program_id"]);$s->execute();$ok=true;}require "../includes/header.php";?><section class="page-banner"><div class="container"><div class="eyebrow">Begin your journey</div><h1 class="display-5 fw-bold mt-3">Online Admission</h1></div></section><section class="section"><div class="container col-lg-8"><?php if($ok):?><div class="alert alert-success">Application submitted successfully.</div><?php endif;?><form method="post" class="dashboard-card"><input class="form-control mb-3" name="name" placeholder="Full name" required><input class="form-control mb-3" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" name="phone" placeholder="Phone" required><select class="form-select mb-3" name="program_id" required><?php while($p=$programs->fetch_assoc()):?><option value="<?=$p["id"]?>"><?=e($p["name"])?></option><?php endwhile;?></select><button class="btn btn-adventure rounded-pill">Submit Application</button></form></div></section><?php require "../includes/footer.php";?>